// Styles
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

import React, { useState, useEffect } from "react";
import { FormattedMessage } from "react-intl";
import { SingleDatePicker } from "react-dates";
import { useHistory } from "react-router-dom";
import Loader from "react-loader-spinner";
import moment from "moment";
import Select from "react-select";
import Pagination2 from "react-js-pagination";

// Redux
import { connect } from "react-redux";
import { downloadAffiliateAcquirerAudit, fetchInterAffiliateAcquirerAudit } from "../../../../actions/filesets";
import { fetchAffiliatesNamesAndCodes, getRegionCodes } from "../../../../actions/affiliates";
import { closeAlert } from "../../../../actions/utils";

// Components
import { Alert, Button, Card, CardBody, CardHeader, Col, Row, Table as Table2 } from "reactstrap";
import PostingTable from "../../../../components/PostingTable";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import ErrorMessage from "../../../../components/ErrorMessage";

// query string
const queryString = require("query-string");

const AcquirerAudit = ({
	// function props
	closeAlert,
	getRegionCodes,
	downloadAffiliateAcquirerAudit,
	fetchAffiliatesNamesAndCodes,
	fetchInterAffiliateAcquirerAudit,
	// query string props
	location                         : { search: queryParams }, // gets the query string from props.search and save it as queryParams
	// state variables props
	alertError,
	download_status,
	regionCodes,
	allAffiliates,
	selectedAffiliateCode,
	acquirerAudit,
	acquirerAuditError,
}) => {
	// QUERY STRING VARIABLES
	// let { affiliateCode } = queryString.parse(queryParams);
	let { settlementDate } = queryString.parse(queryParams);
	let { page } = queryString.parse(queryParams);
	let regionCode = queryString.parse(queryParams)["region-code"];
	let issuerCode = queryString.parse(queryParams)["issuer-code"];
	let acquirerCode = queryString.parse(queryParams)["acquirer-code"];

	const history = useHistory(); // save react router history to history
	const [ focused, setFocused ] = useState(false);

	const [ startDate, setStartDate ] = useState(moment(settlementDate));
	useEffect(
		() => {
			setStartDate(moment(settlementDate));
		},
		[ settlementDate ],
	);

	// React select ony takes objec e.g {label: "USD": value:"USD"} so this construct achieves this but is also dynamic to what ever is passed as the region code in the query string.
	const [ selectedRegion, setSelectedRegion ] = useState({
		label : regionCode,
		value : regionCode,
	});
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setSelectedRegion({
				label : regionCode,
				value : regionCode,
			});
		},
		[ regionCode ],
	);

	// sets selectedIssuer state with the value of issuerCode gotten from the query string above
	const [ selectedIssuer, setselectedIssuer ] = useState({
		label : issuerCode,
		value : issuerCode,
	});

	// updates selectedIssuer as it changes in the questry string
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setselectedIssuer({
				label : issuerCode,
				value : issuerCode,
			});
		},
		[ issuerCode ],
	);

	// sets selectedAcquirer state with the value of issuerCode gotten from the query string above
	const [ selectedAcquirer, setselectedAcquirer ] = useState({
		label : acquirerCode,
		value : acquirerCode,
	});

	// updates selectedAcquirer as it changes in the questry string
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setselectedAcquirer({
				label : acquirerCode,
				value : acquirerCode,
			});
		},
		[ acquirerCode ],
	);

	const [ activePage, setActivePage ] = useState(parseInt(page));
	useEffect(
		() => {
			// handles page change via url
			setActivePage(parseInt(page));
		},
		[ page ],
	);

	// Use Effect Handles General Updates
	useEffect(
		() => {
			const pageQuery = page - 1;
			getRegionCodes();
			fetchAffiliatesNamesAndCodes();
			fetchInterAffiliateAcquirerAudit(settlementDate, regionCode, issuerCode, acquirerCode, pageQuery);
		},
		[ queryParams ],
	);

	const handlePageChange = (pageNumber) => {
		history.push(
			`/interaffiliate/reports/acquirer-audit?settlementDate=${settlementDate}&issuer-code=${issuerCode}&acquirer-code=${acquirerCode}&region-code=${regionCode}&page=${pageNumber}`,
		);
		setActivePage(pageNumber);
	};

	const handleSubmitDate = (selectedDate, region, issuer, acquirer, page) => {
		let settlementDate = moment(selectedDate).format("YYYY-MM-DD");
		history.push(
			`/interaffiliate/reports/acquirer-audit?settlementDate=${settlementDate}&issuer-code=${issuer.value}&acquirer-code=${acquirer.value}&region-code=${region.label}&page=${page}`,
		);
	};

	let SelectRegion = [];
	SelectRegion =
		regionCodes &&
		regionCodes.map((region) => {
			return { label: region.code, value: region };
		});

	// Remove ALL from the list of allAffiliates
	allAffiliates = allAffiliates && allAffiliates.filter((aff) => aff.value !== "ALL");

	const IssuerAuditHeader = [
		"termId",
		"dateTime",
		"trn",
		"cat",
		"audNo",
		"cardNumber",
		"err",
		"rrn",
		"tranAmt",
		"cashAmt",
		"netAmt",
		"accountNumber",
		"rate",
		"ifee",
	];

	const onDismiss = () => {
		closeAlert();
	};

	return (
		<div className='animated fadeIn'>
			{alertError && (
				<Alert color='danger' toggle={onDismiss}>
					{alertError ? alertError : "Error unable to download. Please Check you entries!"}
				</Alert>
			)}
			<Row>
				<Col lg={12}>
					<Card>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<React.Fragment>
									{settlementDate}
									<FormattedMessage id=' Audit' defaultMessage=' Audit' />
								</React.Fragment>
							</strong>

							<div style={{ width: "73%" }} className={"d-flex justify-content-end align-items-center"}>
								<React.Fragment>
									<React.Fragment>
										<SingleDatePicker
											className={"mx-1"}
											showDefaultInputIcon={true}
											date={startDate} // momentPropTypes.momentObj or null
											onDateChange={(startDate) => setStartDate(startDate)} // PropTypes.func.isRequired
											focused={focused} // PropTypes.bool
											onFocusChange={({ focused }) => setFocused(focused)} // PropTypes.func.isRequired
											id='your_unique_id' // PropTypes.string.isRequired,
											isOutsideRange={() => false}
											numberOfMonths={1}
										/>
									</React.Fragment>
									<span style={{ width: "14%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setSelectedRegion(selectedOption)}
											value={selectedRegion}
											options={SelectRegion && SelectRegion}
										/>
									</span>
									<span style={{ width: "16%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setselectedIssuer(selectedOption)}
											value={selectedIssuer}
											options={allAffiliates && allAffiliates}
										/>
									</span>
									<span style={{ width: "16%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setselectedAcquirer(selectedOption)}
											value={selectedAcquirer}
											options={allAffiliates && allAffiliates}
										/>
									</span>
									<Button
										style={{
											padding                : "9px",
											borderTopLeftRadius    : "0px",
											borderBottomLeftRadius : "0px",
										}}
										className={"btn-sm mx-1"}
										onClick={() =>
											handleSubmitDate(
												startDate,
												selectedRegion,
												selectedIssuer,
												selectedAcquirer,
												activePage,
											)}
										color='primary'
									>
										{" "}
										<FormattedMessage id='Submit' defaultMessage='Submit' />
									</Button>
								</React.Fragment>
								<React.Fragment>
									<Button
										className={"btn-sm ml-1"}
										style={{ padding: "8px" }}
										color='success'
										onClick={(e) =>
											downloadAffiliateAcquirerAudit(
												settlementDate,
												regionCode,
												issuerCode,
												acquirerCode,
											)}
									>
										<span className={"d-flex px-2 justify-content-center align-items-center"}>
											<i className='fa fa-download' />&nbsp;
											{download_status ? (
												<Loader
													type='ThreeDots'
													color='#FFF'
													height={20}
													width={20}
													style={{ textAlign: "center" }}
												/>
											) : (
												<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
											)}
										</span>
									</Button>
								</React.Fragment>
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!acquirerAuditError &&
							!acquirerAudit && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle unselected fields */}
							{(regionCode === "Region" || issuerCode === "Issuer" || acquirerCode === "Acquirer") &&
							!acquirerAudit &&
							acquirerAuditError && (
								<ErrorMessage
									message={
										"Please select your Region code, Issuer code, Acquirer Code and click Submit to view entries!"
									}
								/>
							)}

							{/* Handle display on transaction */}
							{acquirerAudit &&
							acquirerAudit.data &&
							acquirerAudit.data.content &&
							acquirerAudit.data.content.length === 0 && (
								<ErrorMessage message={"No trasaction was made today between these affiliates!"} />
							)}

							{/* Handle display 404 Error */}
							{regionCode !== "Region" &&
							issuerCode !== "Issuer" &&
							acquirerCode !== "Acquirer" &&
							!acquirerAudit &&
							acquirerAuditError &&
							acquirerAuditError.data && <ErrorMessage message={acquirerAuditError.data.message} />}

							{/* Handle display content */}
							{acquirerAudit &&
							acquirerAudit.data &&
							acquirerAudit.data.content &&
							acquirerAudit.data.content.length > 0 && (
								<Table2 hover bordered striped responsive size='sm'>
									<thead>
										<PostingTableHeader headerType={"array"} headerPayload={IssuerAuditHeader} />
									</thead>
									<tbody>
										<PostingTable
											tableName={"audit-report"}
											dataRecords={
												acquirerAudit && acquirerAudit.data && acquirerAudit.data.content ? (
													acquirerAudit.data.content
												) : (
													[]
												)
											}
										/>
									</tbody>
								</Table2>
							)}

							{/* Handle Pagination */}
							{acquirerAudit &&
							acquirerAudit.data &&
							acquirerAudit.data.content.length > 0 && (
								<nav>
									<Pagination2
										activePage={activePage}
										itemsCountPerPage={acquirerAudit.data.size}
										totalItemsCount={(acquirerAudit && acquirerAudit.data.totalElements) || null}
										pageRangeDisplayed={20}
										onChange={handlePageChange}
									/>
								</nav>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		alertError         : state.utils.alertError,
		download_status    : state.fileSets.download_status,
		acquirerAudit      : state.fileSets.acquirerAudit,
		acquirerAuditError : state.fileSets.acquirerAuditError,
		regionCodes        : state.affiliates.region_codes,
		allAffiliates      : state.affiliates.affiliatesNamesAndCodes,
	};
};

export default connect(mapStateToProps, {
	closeAlert,
	fetchInterAffiliateAcquirerAudit,
	downloadAffiliateAcquirerAudit,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
})(AcquirerAudit);
